impl Workspace {
    /// Move the tabs after `view` into a new pane. False when `view` is missing or last in its pane.
    pub fn split(&mut self, view: ViewId, axis: Axis) -> bool;
    /// Make `view` the visible tab of its pane and the active view. False when `view` is missing.
    pub fn activate(&mut self, view: ViewId) -> bool;
    /// Every view, pane by pane, left to right and top to bottom.
    pub fn views_in_order(&self) -> Vec<ViewId>;
}
